import json
import os
import fcntl


class KVStore:
    """A simple file-based key-value store using JSON."""

    def __init__(self, path="store.json"):
        self.path = path
        if not os.path.exists(self.path):
            self._write({})

    def _read(self):
        with open(self.path, "r") as f:
            fcntl.flock(f, fcntl.LOCK_SH)
            try:
                return json.load(f)
            finally:
                fcntl.flock(f, fcntl.LOCK_UN)

    def _write(self, data):
        with open(self.path, "w") as f:
            fcntl.flock(f, fcntl.LOCK_EX)
            try:
                json.dump(data, f, indent=2)
            finally:
                fcntl.flock(f, fcntl.LOCK_UN)

    def get(self, key):
        data = self._read()
        if key not in data:
            raise KeyError(key)
        return data[key]

    def set(self, key, value):
        data = self._read()
        data[key] = value
        self._write(data)

    def delete(self, key):
        data = self._read()
        if key not in data:
            raise KeyError(key)
        del data[key]
        self._write(data)

    def keys(self):
        return list(self._read().keys())

    def items(self):
        return list(self._read().items())

    def __contains__(self, key):
        return key in self._read()

    def __len__(self):
        return len(self._read())
